const emit = defineEmits(['select'])
const stages = computed(() => props.groups.filter(group => group !== 'UI recipes').map((name, index) => ({ name, index, items: props.catalog.filter(item => item.group === name) })))
const recipes = computed(() => props.catalog.filter(item => item.group === 'UI recipes'))
const notes = computed(() => [
  { title: 'Kenalan dulu, satu komponen setiap langkah.', description: 'Mulai dari teks, tombol, dan ikon. Hal-hal kecil ini akan jadi bahan untuk hampir setiap layar yang kamu buat.' },
