  { title: 'Alurnya mulai terasa. Yuk beri sentuhan akhir.', review: 'Menu membantu pengguna menemukan tujuan. Dialog dan bottom sheet memberi informasi pada saat yang tepat.', description: 'Sekarang bermainlah dengan warna, bentuk, dan gerakan sederhana agar perubahan di layar lebih mudah dipahami. Sedikit sentuhan bisa membuat UI terasa lebih nyaman.', recall: 'Coba ingat: kapan informasi lebih pas muncul sebagai dialog?' },
])
const combinations = {
  'coffee-shop': ['Katalog', 'Counter', 'Tombol'], settings: ['Pilihan', 'Slider', 'Layout'], dashboard: ['Kartu', 'Progres', 'Layout'],
  'login-page': ['Input', 'Validasi', 'Feedback'], checkout: ['Counter', 'Total belanja', 'Konfirmasi'], inbox: ['Daftar', 'Empty state'],
